        "dua_laylatul_qadr" to DuaText("Мольба ночи предопределения", "О Аллах, поистине, Ты Прощающий и любишь прощать, прости же меня.", "Этому научил Пророк ﷺ Аишу (да будет доволен ею Аллах) для Ночи предопределения.", "Особая мольба для последних десяти ночей Рамадана и Ночи предопределения."),
        "dua_family_coolness" to DuaText("Отрада очей от семьи", "Господь наш, даруй нам от наших супругов и потомков отраду очей и сделай нас образцом для богобоязненных.", "Кораническая мольба о праведном супруге и потомстве.", "Для спокойствия дома и праведного потомства."),
        "dua_righteous_children" to DuaText("Праведное потомство", "Господь мой, даруй мне от Себя чистое потомство. Поистине, Ты слышишь мольбу.", "Мольба пророка Закарии (мир ему).", "Кораническая мольба для желающих детей."),
        "dua_ibrahim_prayer_family" to DuaText("Совершение молитвы", "Господь мой, сделай меня совершающим молитву, и из моего потомства тоже. Господь наш, прими мою мольбу. Господь наш, прости меня, моих родителей и верующих в День расчёта.", "Мольба пророка Ибрахима (мир ему) за себя и своё потомство.", "Часто произносится в конце молитвы."),
        "dua_newlywed" to DuaText("Поздравление молодожёнам", "Да благословит тебя Аллах, да пошлёт благословение на тебя и да соединит вас обоих во благе.", "Произносится тому, кто женился.", "Сунна-поздравление на свадьбу."),
        "dua_before_eating" to DuaText("Перед едой", "Именем Аллаха. (Если забыл:) Именем Аллаха в начале и в конце.", "Перед едой; если забыл, произноси это в середине.", "Произнесение Бисмилля не даёт шайтану участвовать в еде."),
