        "dua_ruqyah_pain" to DuaText("Мольба от боли в теле", "Я прибегаю к Аллаху и Его могуществу от зла того, что я чувствую и чего опасаюсь.", "Положить руку на место боли, трижды произнести Бисмилля, затем эту мольбу семь раз.", "Пророк ﷺ научил этому Усмана ибн Абиль-Аса (да будет доволен им Аллах) от боли."),
        "dua_ruqyah_nabawi" to DuaText("Пророческая рукъя для больного", "О Аллах, Господь людей, устрани вред, исцели, ведь Ты Исцеляющий; нет исцеления, кроме Твоего исцеления — исцеления, не оставляющего болезни.", "С проведением рукой по больному.", "Пророк ﷺ произносил это, посещая больных членов своей семьи."),
        "dua_kalimat_tammat" to DuaText("Прибегание к совершенным словам Аллаха", "Я прибегаю к совершенным словам Аллаха от зла того, что Он сотворил.", "При остановке в каком-либо месте или вечером.", "Кто остановится в каком-либо месте и произнесёт это, тому ничто не навредит, пока он не покинет это место."),
        "dua_evil_eye" to DuaText("Защита детей от сглаза", "Я прошу защиты для вас обоих совершенными словами Аллаха от всякого шайтана, всякой ядовитой твари и от всякого дурного глаза.", "Пророк ﷺ читал это над Хасаном и Хусейном (да будет доволен ими Аллах).", "Сунна-мольба для защиты детей от сглаза и вреда."),
        "dua_seeing_afflicted" to DuaText("При виде испытываемого бедой", "Хвала Аллаху, избавившему меня от того, чем Он испытал тебя, и отдавшему мне предпочтение перед многими из тех, кого Он сотворил.", "При виде человека, испытываемого бедой (произносится про себя).", "Тот, кто это произнесёт, будет защищён от этого испытания."),
        "dua_istikhara" to DuaText("Молитва истихара", "О Аллах, поистине, я прошу у Тебя блага, зная о нём от Тебя, и прошу у Тебя мощи, зная о ней от Тебя, и прошу у Тебя из Твоей великой милости. Поистине, Ты можешь, а я не могу, и Ты знаешь, а я не знаю, и Ты Знающий сокровенное. О Аллах, если Ты знаешь, что это дело благо для меня в моей религии, в моей жизни и в конце моих дел, то предопредели его мне, облегчи мне его и благослови меня в нём. А если Ты знаешь, что это дело плохо для меня в моей религии, в моей жизни и в конце моих дел, то отврати его от меня и отврати меня от него, и предопредели мне благо, где бы оно ни было, а затем удовлетвори меня им.", "После двух ракаатов дополнительной молитвы, когда нужно выбрать лучшее в дозволенном деле.", "Пророк ﷺ учил сподвижников истихаре, как учил их суре из Корана."),
        "dua_allahumma_bika_asbahna" to DuaText("О Аллах, Тобою мы встретили утро", "О Аллах, Тобою мы встретили утро и Тобою мы встретили вечер, Тобою мы живём и Тобою умираем, и к Тебе воскрешение.", "Утром.", "Пророк ﷺ учил сподвижников произносить это утром и вечером."),
        "dua_allahumma_bika_amsayna" to DuaText("О Аллах, Тобою мы встретили вечер", "О Аллах, Тобою мы встретили вечер и Тобою мы встретили утро, Тобою мы живём и Тобою умираем, и к Тебе возвращение.", "Вечером.", "Пророк ﷺ учил сподвижников произносить это утром и вечером."),
        "dua_afiyah_morning" to DuaText("Мольба о благополучии", "О Аллах, поистине, я прошу у Тебя прощения и благополучия в этом мире и в вечной жизни.", "Пророк ﷺ никогда не оставлял эту мольбу утром и вечером.", "Никому не было даровано ничего лучше, чем благополучие."),
        "dua_afini_fi_badani" to DuaText("Благополучие тела, слуха и зрения", "О Аллах, дай благополучие моему телу. О Аллах, дай благополучие моему слуху. О Аллах, дай благополучие моему зрению. Нет божества, кроме Тебя.", "Произносится трижды утром и вечером.", "Мольба о здоровье и сохранности органов чувств."),
        "dua_ya_hayyu_aslih" to DuaText("Исправь для меня все мои дела", "О Живой, о Вседержитель, Твоей милостью я прошу помощи: исправь для меня все мои дела и не оставляй меня самому себе ни на мгновение ока.", "Пророк ﷺ посоветовал Фатиме (да будет доволен ею Аллах) произносить это утром и вечером.", "Просьба о помощи Аллаха во всяком деле."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Тасбих Джувайрии (да будет доволен ею Аллах)", "Пречист Аллах, и хвала Ему — числом Его творений, соответственно Его довольству, весом Его Трона и чернилами Его слов.", "Произносится трижды утром — тяжелее многих часов поминания.", "Эти четыре фразы, произнесённые трижды, перевешивают поминание с рассвета до полудня."),
        "dua_salawat" to DuaText("Ибрахимова молитва за Пророка", "О Аллах, благослови Мухаммада ﷺ и семью Мухаммада, как Ты благословил Ибрахима (мир ему) и семью Ибрахима; Ты Достохвальный, Славный. О Аллах, ниспошли благодать Мухаммаду ﷺ и семье Мухаммада, как Ты ниспослал благодать Ибрахиму (мир ему) и семье Ибрахима; Ты Достохвальный, Славный.", "Салават Пророку ﷺ в молитве и во всякое время.", "Кто пошлёт салават однажды, тому Аллах пошлёт десятикратную милость."),
        "dua_wudu_after" to DuaText("После омовения", "Свидетельствую, что нет божества, кроме Аллаха, Единственного, без сотоварища, и свидетельствую, что Мухаммад ﷺ — Его раб и Посланник. О Аллах, сделай меня из числа кающихся и очищающихся.", "После завершения омовения.", "Ему открываются восемь врат Рая, через любые из которых он может войти."),
        "dua_wudu_before" to DuaText("Перед омовением", "Именем Аллаха.", "При начале омовения.", "Нет (полного) омовения у того, кто не упомянул имя Аллаха над ним."),
        "dua_istiftah" to DuaText("Вступительная мольба молитвы", "Пречист Ты, о Аллах, и хвала Тебе. Благословенно имя Твоё, и возвышенно величие Твоё, и нет божества, кроме Тебя.", "В начале молитвы, сразу после вступительного такбира.", "Сунна-мольба, открывающая молитву."),
        "dua_ruku" to DuaText("В поясном поклоне", "Пречист мой Господь Великий.", "Произносится минимум трижды в поясном поклоне.", "Сунна-тасбих поясного поклона."),
        "dua_sujood" to DuaText("В земном поклоне", "Пречист мой Господь Высочайший.", "Произносится минимум трижды в земном поклоне.", "Раб ближе всего к своему Господу, находясь в земном поклоне."),
        "dua_rising_ruku" to DuaText("При выпрямлении из поясного поклона", "Слышит Аллах того, кто восхваляет Его. Господь наш, Тебе хвала.", "При выпрямлении из поясного поклона и вставании прямо.", "Кто произнесёт это одновременно с ангелами, тому прощаются прошлые грехи."),
        "dua_between_sajdas" to DuaText("Между двумя земными поклонами", "Господь мой, прости меня. Господь мой, прости меня.", "Во время сидения между двумя земными поклонами.", "Сунна-мольба сидения между земными поклонами."),
        "dua_before_salam_four" to DuaText("Прибегание от четырёх вещей перед саламом", "О Аллах, я прибегаю к Тебе от мучений Ада, от мучений могилы, от искушений жизни и смерти, и от зла искушения Лжемессии (Даджаля).", "После последнего ташаххуда и салавата, перед саламом.", "Пророк ﷺ повелел прибегать от этих четырёх вещей."),
        "dua_qunoot_witr" to DuaText("Мольба кунут в витре", "О Аллах, наставь меня в числе тех, кого Ты наставил, дай мне благополучие в числе тех, кому Ты дал благополучие, возьми меня под Своё покровительство в числе тех, кого Ты взял под Своё покровительство, благослови меня в том, что Ты даровал, и защити меня от зла того, что Ты предопределил. Ты предопределяешь, и никто не предопределяет против Тебя, и тот, кого Ты берёшь в друзья, никогда не унижается. Благословен Ты, Господь наш, и возвышен.", "В молитве витр — Пророк ﷺ научил этому Хасана ибн Али (да будет доволен им Аллах).", "Сунна-кунут витра."),
        "dua_qunoot_hanafi" to DuaText("Кунут (О Аллах, мы просим Твоей помощи)", "О Аллах, мы просим Твоей помощи, просим Твоего прощения, веруем в Тебя, уповаем на Тебя, восхваляем Тебя наилучшим образом, благодарим Тебя и не проявляем неблагодарности, и оставляем тех, кто ослушивается Тебя. О Аллах, лишь Тебе мы поклоняемся, Тебе молимся и совершаем земной поклон, к Тебе устремляемся и спешим, надеемся на Твою милость и боимся Твоего наказания; поистине, Твоё наказание непременно постигнет неверующих.", "В витре — практика ханафитов.", "Передано от Умара (да будет доволен им Аллах) в кунуте."),
        "dua_sleep_aslamtu" to DuaText("Последние слова перед сном", "О Аллах, я предаю себя Тебе, поручаю своё дело Тебе и вверяю свою спину Твоей защите, надеясь на Тебя и страшась Тебя. Нет убежища и спасения от Тебя, кроме как у Тебя. Я уверовал в Твою Книгу, которую Ты ниспослал, и в Твоего Пророка, которого Ты послал.", "После омовения, лёжа на правом боку — самые последние слова перед сном.", "Если он умрёт этой ночью, он умрёт на естественной вере (фитре)."),
        "dua_waking_night" to DuaText("При пробуждении ночью", "Нет божества, кроме Аллаха, Единственного, без сотоварища. Ему принадлежит власть и хвала, и Он над всякой вещью мощен. Хвала Аллаху, пречист Аллах, нет божества, кроме Аллаха, Аллах Велик, и нет мощи и силы, кроме как от Аллаха. О Аллах, прости меня.", "При пробуждении ночью.", "Его мольба принимается, и если он совершит омовение и помолится, его молитва будет принята."),
        "dua_hamm_ibn_masud" to DuaText("Мольба от печали (Ибн Масуд)", "О Аллах, я Твой раб, сын Твоего раба, сын Твоей рабыни. Мой чуб в Твоей руке, Твоё повеление надо мной исполняется, и Твой приговор относительно меня справедлив. Я прошу Тебя каждым именем, которое принадлежит Тебе, которым Ты назвал Себя, или ниспослал в Своей Книге, или научил кого-либо из Своих творений, или оставил при Себе в знании сокровенного, — сделать Коран весной моего сердца, светом моей груди, устранением моей печали и уходом моей тревоги.", "В печали и бедствии — Аллах заменяет печаль радостью.", "Аллах устраняет его тревогу и печаль и дарует ему взамен радость."),
        "dua_difficulty_sahl" to DuaText("При трудности дела", "О Аллах, нет ничего лёгкого, кроме того, что Ты сделал лёгким, и Ты делаешь трудное лёгким, если пожелаешь.", "Когда что-то кажется трудным.", "Облегчение на экзаменах и в трудных делах."),
        "dua_musibah" to DuaText("При беде (аль-истирджа)", "Поистине, мы принадлежим Аллаху, и, поистине, к Нему мы вернёмся. О Аллах, вознагради меня за мою беду и замени мне её лучшим.", "При любой утрате или беде.", "Аллах непременно даёт лучшее взамен — как это случилось с Умм Салямой (да будет доволен ею Аллах)."),
        "dua_debt" to DuaText("Избавление от долга", "О Аллах, избавь меня дозволенным Тобою от запретного, и обогати меня Своей милостью от всех, кроме Тебя.", "Для выплаты долга — этому научил Али (да будет доволен им Аллах).", "Даже если долг подобен горе, Аллах погасит его."),
        "dua_anger" to DuaText("При гневе", "Я прибегаю к Аллаху от проклятого шайтана.", "При гневе.", "Пророк ﷺ сказал: если он произнесёт это, его гнев пройдёт."),
        "dua_waswasa" to DuaText("Против наущений о вере", "Я уверовал в Аллаха и Его посланников.", "При наущениях шайтана о вере.", "Когда приходит наущение, произнеси это и остановись на этом (а также прибегни к Аллаху)."),
        "dua_travel_full" to DuaText("Полная мольба в пути", "О Аллах, мы просим Тебя в этом нашем путешествии о праведности и богобоязненности, и о делах, которые Тебе угодны. О Аллах, облегчи нам это путешествие и сократи его расстояние. О Аллах, Ты Спутник в пути и Хранитель семьи.", "При отправлении в путь, после 'Пречист Тот, Кто подчинил'.", "Полная сунна-мольба в пути."),
        "dua_return_travel" to DuaText("При возвращении из поездки", "Мы возвращаемся, каясь, поклоняясь и восхваляя нашего Господа.", "При возвращении из поездки.", "Пророк ﷺ говорил это, возвращаясь из поездки."),
        "dua_farewell_traveller" to DuaText("Прощание с путником", "Я вверяю Аллаху твою религию, твою честь и исход твоих дел.", "При прощании с путником.", "То, что вверено Аллаху, никогда не пропадает."),
        "dua_entering_town" to DuaText("Остановка в новом месте", "Я прибегаю к совершенным словам Аллаха от зла того, что Он сотворил.", "При остановке в новом месте или городе.", "Ему ничто не навредит, пока он не покинет это место."),
        "dua_boarding_ship" to DuaText("Посадка на корабль", "Именем Аллаха его плавание и его стоянка; поистине, мой Господь — Прощающий, Милосердный.", "При посадке на корабль — слова пророка Нуха (мир ему).", "Кораническая мольба ковчега Нуха (мир ему)."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Покаяние через Живого, Вседержителя", "Я прошу прощения у Аллаха, кроме Которого нет божества, Живого, Вседержителя, и обращаюсь к Нему с покаянием.", "Для покаяния.", "Его грехи прощаются, даже если он бежал с поля битвы."),
        "dua_rabbighfir_warham" to DuaText("Господь мой, прости и помилуй", "Господь мой, прости и помилуй, ведь Ты — лучший из милующих.", "Кораническая мольба — о прощении и милости.", "Последний аят суры аль-Муминун."),
        "dua_majlis_kaffarah" to DuaText("Искупление собрания", "Пречист Ты, о Аллах, и хвала Тебе. Свидетельствую, что нет божества, кроме Тебя. Прошу у Тебя прощения и обращаюсь к Тебе с покаянием.", "При вставании с собрания.", "Это становится искуплением за то, что было сказано напрасного на собрании."),
        "dua_jami_forgiveness" to DuaText("Всеобъемлющая мольба о прощении", "О Аллах, прости мне мои ошибки, моё невежество и мою чрезмерность в моих делах, и то, что Ты знаешь лучше меня.", "Всеобъемлющая мольба Пророка ﷺ.", "Пророк ﷺ часто произносил эту мольбу."),
        "dua_parents_nuh" to DuaText("Мольба пророка Нуха за родителей", "Господь мой, прости меня, моих родителей, всякого, кто войдёт в мой дом верующим, и всех верующих мужчин и верующих женщин.", "За родителей и верующих.", "Мольба пророка Нуха (мир ему)."),
        "dua_shukr_parents" to DuaText("Благодарность за родителей и праведное потомство", "Господь мой, внуши мне быть благодарным за Твою милость, которую Ты оказал мне и моим родителям, и совершать праведные дела, которыми Ты доволен, и сделай праведным моё потомство. Я обращаюсь к Тебе с покаянием, и я один из предавшихся.", "Кораническая мольба достижения сорока лет.", "Благодарность, добрые дела и праведность потомства — всё в одной мольбе."),
        "dua_intimacy" to DuaText("Перед близостью супругов", "Именем Аллаха. О Аллах, удали от нас шайтана и удали шайтана от того, чем Ты нас наделишь.", "Перед супружеской близостью.", "Если будет предопределён ребёнок, шайтан никогда не навредит ему."),
        "dua_ibrahim_children_protection" to DuaText("Защита города и потомства", "Господь мой, сделай этот город безопасным и убереги меня и моих сыновей от поклонения идолам.", "Мольба пророка Ибрахима (мир ему) о безопасности города и потомства.", "Мольба о стойкости в единобожии."),
        "dua_drinking_milk" to DuaText("При питье молока", "О Аллах, благослови нам его и умножь нам его.", "При питье молока.", "Молоко заменяет и еду, и питьё."),
        "dua_iftar_host" to DuaText("Разговение у другого человека", "Пусть постящиеся разговляются у вас, пусть праведные едят вашу еду, и пусть ангелы молятся за вас.", "При разговении в гостях у кого-либо.", "Мольба Пророка ﷺ за хозяина дома."),
        "dua_seeing_first_fruit" to DuaText("При виде первого плода", "О Аллах, благослови нам наши плоды, благослови нам наш город и благослови нам наши меры саа и мудд.", "При виде первого плода сезона.", "Мольба о благословении в уделе и в своём городе."),
        "dua_good_news" to DuaText("При хорошей вести", "Хвала Аллаху, по чьей милости совершаются благие дела.", "При получении хорошей вести (и совершении земного поклона благодарности).", "Пророк ﷺ говорил это, увидев то, что ему нравилось."),
        "dua_looking_mirror" to DuaText("При взгляде в зеркало", "О Аллах, как Ты сделал прекрасным мой облик, так сделай прекрасным и мой нрав.", "При взгляде в зеркало.", "Пророк ﷺ произносил эту мольбу."),
        "dua_rabbana_taqabbal" to DuaText("Принятие деяний", "Господь наш, прими от нас, ведь Ты — Слышащий, Знающий. И прими наше покаяние, ведь Ты — Принимающий покаяние, Милосердный.", "Мольба Ибрахима и Исмаила (мир им) при строительстве Каабы.", "Мольба о принятии после совершения всякого благого дела."),
    )
}
